    clientHintIssueDetails: ?ClientHintIssueDetails = null,
    federatedAuthRequestIssueDetails: ?FederatedAuthRequestIssueDetails = null,
    bounceTrackingIssueDetails: ?BounceTrackingIssueDetails = null,
    cookieDeprecationMetadataIssueDetails: ?CookieDeprecationMetadataIssueDetails = null,
    stylesheetLoadingIssueDetails: ?StylesheetLoadingIssueDetails = null,
    propertyRuleIssueDetails: ?PropertyRuleIssueDetails = null,
    federatedAuthUserInfoRequestIssueDetails: ?FederatedAuthUserInfoRequestIssueDetails = null,
    sharedDictionaryIssueDetails: ?SharedDictionaryIssueDetails = null,
    elementAccessibilityIssueDetails: ?ElementAccessibilityIssueDetails = null,
    sriMessageSignatureIssueDetails: ?SRIMessageSignatureIssueDetails = null,
    unencodedDigestIssueDetails: ?UnencodedDigestIssueDetails = null,
    connectionAllowlistIssueDetails: ?ConnectionAllowlistIssueDetails = null,
    userReidentificationIssueDetails: ?UserReidentificationIssueDetails = null,
    permissionElementIssueDetails: ?PermissionElementIssueDetails = null,
    performanceIssueDetails: ?PerformanceIssueDetails = null,
    selectivePermissionsInterventionIssueDetails: ?SelectivePermissionsInterventionIssueDetails = null,
    emailVerificationRequestIssueDetails: ?EmailVerificationRequestIssueDetails = null,
    lazyLoadImageIssueDetails: ?LazyLoadImageIssueDetails = null,
    webInstallIssueDetails: ?WebInstallIssueDetails = null,
};

/// A unique id for a DevTools inspector issue. Allows other entities (e.g.
/// exceptions, CDP message, console messages, etc.) to reference an issue.
pub const IssueId = []const u8;

/// An inspector issue reported from the back-end.
pub const InspectorIssue = struct {
    code: InspectorIssueCode,
    details: InspectorIssueDetails,
    /// A unique id for this issue. May be omitted if no other entity (e.g.
    /// exception, CDP message, etc.) is referencing this issue.
    issueId: ?IssueId = null,
};

/// Every command of the domain, by name.
pub const CommandName = enum {
    getEncodedResponse,
    disable,
    enable,
    checkFormsIssues,
};

/// Every event of the domain, by name.
pub const EventName = enum {
    issueAdded,
};

/// Returns the response body and size if it were re-encoded with the specified settings. Only
/// applies to images.
pub const getEncodedResponse = struct {
    pub const method = "Audits.getEncodedResponse";
    pub const Params = struct {
        /// Identifier of the network request to get content for.
        requestId: protocol.Network.RequestId,
        /// The encoding to use.
        encoding: enum {
            webp,
            jpeg,
            png,
        },
        /// The quality of the encoding (0-1). (defaults to 1)
        quality: ?f64 = null,
        /// Whether to only return the size information (defaults to false).
        sizeOnly: ?bool = null,
    };
    pub const Result = struct {
        /// The encoded body as a base64 string. Omitted if sizeOnly is true. (Encoded as a base64 string when passed over JSON)
        body: ?[]const u8 = null,
        /// Size before re-encoding.
        originalSize: i64,
        /// Size after re-encoding.
        encodedSize: i64,
    };
};

/// Disables issues domain, prevents further issues from being reported to the client.
pub const disable = struct {
    pub const method = "Audits.disable";
    pub const Params = struct {};
    pub const Result = struct {};
};

/// Enables issues domain, sends the issues collected so far to the client by means of the
/// `issueAdded` event.
pub const enable = struct {
    pub const method = "Audits.enable";
    pub const Params = struct {};
    pub const Result = struct {};
};

/// Runs the form issues check for the target page. Found issues are reported
/// using Audits.issueAdded event.
pub const checkFormsIssues = struct {
    pub const method = "Audits.checkFormsIssues";
    pub const Params = struct {};
    pub const Result = struct {
        formIssues: []const GenericIssueDetails,
    };
};

pub const issueAdded = struct {
    pub const method = "Audits.issueAdded";
    pub const Params = struct {
        issue: InspectorIssue,
    };
};
